import{d as t}from"./chunks/release.data.Crw_-uyu.js";import{c as i,o as s,ah as n,j as e,t as r,k as o}from"./chunks/framework.CKKOjZuE.js";const l={tabindex:"0"},d={style:{"text-align":"left"}},h={style:{"text-align":"left"}},c={style:{"text-align":"left"}},g=JSON.parse('{"title":"About Moseq-Reports","description":"","frontmatter":{},"headers":[],"relativePath":"About.md","filePath":"About.md","lastUpdated":1749679150000}'),p={name:"About.md"},y=Object.assign(p,{setup(u){return(m,a)=>(s(),i("div",null,[a[4]||(a[4]=n('<h1 id="about-moseq-reports" tabindex="-1">About Moseq-Reports <a class="header-anchor" href="#about-moseq-reports" aria-label="Permalink to &quot;About Moseq-Reports&quot;">​</a></h1><p>Interactive interrogation of MoSeq models.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>In short, moseq-reports exists to democratize MoSeq data. Computational biologists often produce data which is difficult to parse without the proper tools or context, increasing access barriers for others to simply pick up and use. Moseq-reports allows wet-lab researchers to easily understand MoSeq models without having to reference outside sources or learn programming languages and manage complex software environments. This program reports data in a form which can be quickly understood by researchers while also providing a set of robust tools to reformat that data in such a way that would be most beneficial to their research.</p><h2 id="papers-that-have-utilized-moseq-reports" tabindex="-1">Papers that have utilized moseq-reports <a class="header-anchor" href="#papers-that-have-utilized-moseq-reports" aria-label="Permalink to &quot;Papers that have utilized moseq-reports&quot;">​</a></h2><p>Below is a listing of papers that have utilized moseq-reports in one way or another.</p><ul><li><p>A Tucker et al. Functional synaptic connectivity of engrafted spinal cord neurons with locomotor circuitry in the injured spinal cord. bioRxiv. April 5, 2025. <a href="https://doi.org/10.1101/2025.04.05.644402" target="_blank" rel="noreferrer">10.1101/2025.04.05.644402</a>.</p></li><li><p>JT Eisdorfer, JK Thackray et al. Using behavioral biomarkers to redefine epochs of spontaneous recovery following spinal cord injury. bioRxiv. February 13, 2025. <a href="https://doi.org/10.1101/2023.10.31.564826" target="_blank" rel="noreferrer">10.1101/2023.10.31.564826</a>.</p></li><li><p>C Nasello et al. Human mutations in high-confidence Tourette disorder genes affect sensorimotor behavior, reward learning, and striatal dopamine in mice. PNAS. April 29, 2024. <a href="https://doi.org/10.1073/pnas.2307156121" target="_blank" rel="noreferrer">10.1073/pnas.2307156121</a>.</p></li><li><p>MA Gradwell, N Ozeri-Engelhard et al. Multimodal sensory control of motor performance by glycinergic interneurons of the mouse spinal cord deep dorsal horn. Neuron. March 6, 2024. <a href="https://doi.org/10.1016/j.neuron.2024.01.027" target="_blank" rel="noreferrer">10.1016/j.neuron.2024.01.027</a>.</p></li><li><p>M Bohic, LA Pattison et al. Mapping the neuroethological signatures of pain, analgesia and recovery in mice. Neuron. July 12, 2023. <a href="https://doi.org/10.1016/j.neuron.2023.06.008" target="_blank" rel="noreferrer">10.1016/j.neuron.2023.06.008</a>.</p></li><li><p>LA Poppi et al. A cadherin mutation in Celsr3 linked to Tourette Disorder affects dendritic patterning and excitability of cholinergic interneurons. bioRxiv. March 7, 2022. <a href="https://doi.org/10.1101/2022.03.06.483205" target="_blank" rel="noreferrer">10.1101/2022.03.06.483205</a>.</p></li></ul><h2 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h2><h3 id="what-is-moseq" tabindex="-1">What is MoSeq <a class="header-anchor" href="#what-is-moseq" aria-label="Permalink to &quot;What is MoSeq&quot;">​</a></h3><p>MoSeq is short for motion sequencing. Using a depth camera, mice are recorded freely behaving in an arena. These videos are analyzed and labeled for specific syllables using machine learning. MoSeq was first described in <a href="https://doi.org/10.1016/j.neuron.2015.11.031" target="_blank" rel="noreferrer"><code>Wiltschko et al. 2015. DOI: 10.1016/j.neuron.2015.11.031</code></a>, but many papers utilizing this technology have since been published. If you are interested in using MoSeq, please visit the <a href="https://dattalab.github.io/moseq2-website/index.html" target="_blank" rel="noreferrer">MoSeq homepage</a>. Once you have collected and modelled data with MoSeq, come back and use moseq-reports for your analysis!</p><h3 id="what-is-a-syllable" tabindex="-1">What is a syllable <a class="header-anchor" href="#what-is-a-syllable" aria-label="Permalink to &quot;What is a syllable&quot;">​</a></h3><p>A syllable is a stereotyped, reusable, action performed by an animal, as learned by the MoSeq algorithm. Syllables are concatenated in time (through transitions) to build up larger and more complex behaviors. Syllables are described by a linear dynamical system using 3D pose information (like that provided by a depth camera). Along with syllables, there is a grammar which dictates the way in which these syllables are put together (transitions). How often a Syllable is used by an animal can be summarized by counting the number of emissions (AKA counting by <code>usage</code>) or by summing the number of frames in which the animal is performing the Syllable (AKA counting by <code>frames</code>).</p><h3 id="msq-files" tabindex="-1"><code>*.msq</code> Files <a class="header-anchor" href="#msq-files" aria-label="Permalink to &quot;`*.msq` Files&quot;">​</a></h3><p>MSQ Files are the format from which the moseq-reports program reads data including video clips, usage data, transitions data, and other data. Think of it as a word document which requires the Microsoft Word program to access. Should you want to access the data stored in the msq file directly, you can change the extension from <code>.msq</code> to <code>.zip</code> and open it using a file archiver such as 7-Zip. For specific information on MSQ files, referenced the <a href="./dev_guide/MSQInternals.html">Developer Guide</a>.</p><h2 id="version-details" tabindex="-1">Version Details <a class="header-anchor" href="#version-details" aria-label="Permalink to &quot;Version Details&quot;">​</a></h2>',15)),e("table",l,[a[3]||(a[3]=e("thead",null,[e("tr",null,[e("th",{style:{"text-align":"left"}},"Identifier"),e("th",{style:{"text-align":"left"}},"Value")])],-1)),e("tbody",null,[e("tr",null,[a[0]||(a[0]=e("td",{style:{"text-align":"left"}},"App Version",-1)),e("td",d,r(o(t).appVersion),1)]),e("tr",null,[a[1]||(a[1]=e("td",{style:{"text-align":"left"}},"Branch/Tag",-1)),e("td",h,r(o(t).commitRef),1)]),e("tr",null,[a[2]||(a[2]=e("td",{style:{"text-align":"left"}},"Commit Hash",-1)),e("td",c,r(o(t).commitHash),1)])])])]))}});export{g as __pageData,y as default};
